// ============================================================
// SalesGenie - Email Ingestion Agent Evaluation
// ============================================================


// ============================================================
// 1. AI AGENT OUTPUT
// ============================================================

let actual = $json.output;

if (typeof actual === "string") {
  try {
    actual = JSON.parse(actual);
  } catch (e) {
    actual = {};
  }
}

if (!actual || typeof actual !== "object") {
  actual = {};
}


// ============================================================
// 2. GROUND TRUTH FROM EVALUATION DATASET
// ============================================================

const dataset =
  $("When fetching a dataset row").item.json;


// ============================================================
// 3. BASIC NORMALIZATION
// ============================================================

function normalize(value) {

  if (
    value === undefined ||
    value === null ||
    String(value).trim() === ""
  ) {
    return "unknown";
  }

  return String(value)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}


// ============================================================
// 4. MONEY NORMALIZATION
// ============================================================

function normalizeMoney(value) {

  if (
    value === undefined ||
    value === null ||
    String(value).trim() === ""
  ) {
    return "unknown";
  }

  const str =
    String(value)
      .toLowerCase()
      .replace(/,/g, "")
      .replace(/\$/g, "")
      .replace(/usd/g, "")
      .replace(/₹/g, "")
      .replace(/inr/g, "")
      .trim();

  // Handle "under 800", "up to 800", etc.
  const match =
    str.match(/(\d+(?:\.\d+)?)/);

  if (match) {
    return String(Number(match[1]));
  }

  return normalize(value);
}


// ============================================================
// 5. QUANTITY NORMALIZATION
// ============================================================

function normalizeQuantity(value) {

  if (
    value === undefined ||
    value === null ||
    String(value).trim() === ""
  ) {
    return "unknown";
  }

  const str =
    String(value)
      .toLowerCase()
      .replace(/,/g, "")
      .trim();

  const match =
    str.match(/\d+(?:\.\d+)?/);

  if (match) {
    return String(Number(match[0]));
  }

  return normalize(value);
}


// ============================================================
// 6. URGENCY NORMALIZATION
// ============================================================

function normalizeUrgency(value) {

  const normalized =
    normalize(value);

  if (normalized === "unknown") {
    return "unknown";
  }

  return normalized
    .replace(/^by\s+/, "")
    .replace(/^within\s+/, "")
    .replace(/^before\s+/, "")
    .replace(/^no later than\s+/, "")
    .replace(/^deadline:\s*/, "")
    .replace(/\s+/g, " ")
    .trim();
}


// ============================================================
// 7. EXPECTED VALUES
// ============================================================

const expected = {

  customer_name:
    dataset.expected_customer_name,

  customer_email:
    dataset.expected_customer_email,

  product_interest:
    dataset.expected_product_interest,

  budget:
    dataset.expected_budget,

  quantity:
    dataset.expected_quantity,

  urgency:
    dataset.expected_urgency,

  requirements:
    dataset.expected_requirements

};


// ============================================================
// 8. FIELD EXTRACTION ACCURACY
// ============================================================

const fields = [
  "customer_name",
  "customer_email",
  "product_interest",
  "budget",
  "quantity",
  "urgency"
];

let correct = 0;

const field_results = {};


for (const field of fields) {

  let expectedValue;
  let actualValue;


  if (field === "budget") {

    expectedValue =
      normalizeMoney(expected[field]);

    actualValue =
      normalizeMoney(actual[field]);

  }

  else if (field === "quantity") {

    expectedValue =
      normalizeQuantity(expected[field]);

    actualValue =
      normalizeQuantity(actual[field]);

  }

  else if (field === "urgency") {

    expectedValue =
      normalizeUrgency(expected[field]);

    actualValue =
      normalizeUrgency(actual[field]);

  }

  else {

    expectedValue =
      normalize(expected[field]);

    actualValue =
      normalize(actual[field]);

  }


  const match =
    expectedValue === actualValue;


  if (match) {
    correct++;
  }


  field_results[field] = {

    expected:
      expectedValue,

    actual:
      actualValue,

    match:
      match

  };

}


const field_extraction_accuracy =
  Number(
    (
      correct /
      fields.length
    ).toFixed(2)
  );


// ============================================================
// 9. COMPLETENESS SCORE
// ============================================================
//
// IMPORTANT:
//
// "unknown" is a valid value.
//
// If the email does not provide quantity or urgency and the
// agent returns:
//
// quantity: "unknown"
// urgency: "unknown"
//
// those fields ARE considered present.
//
// Only a completely missing field counts as incomplete.
// ============================================================

const requiredFields = [
  "customer_name",
  "customer_email",
  "product_interest",
  "budget",
  "quantity",
  "urgency",
  "requirements"
];

let presentFields = 0;

const completeness_results = {};


for (const field of requiredFields) {

  const exists =
    Object.prototype.hasOwnProperty.call(
      actual,
      field
    );


  if (exists) {

    presentFields++;

    completeness_results[field] = {

      present:
        true,

      value:
        actual[field]

    };

  }
  else {

    completeness_results[field] = {

      present:
        false,

      value:
        null

    };

  }

}


const completeness_score =
  Number(
    (
      presentFields /
      requiredFields.length
    ).toFixed(2)
  );


// ============================================================
// 10. FORMAT COMPLIANCE
// ============================================================

const allFieldsPresent =
  requiredFields.every(
    field =>
      Object.prototype.hasOwnProperty.call(
        actual,
        field
      )
  );


const requirementsIsArray =
  Array.isArray(
    actual.requirements
  );


const format_compliance =
  (
    allFieldsPresent &&
    requirementsIsArray
  )
    ? 1
    : 0;


// ============================================================
// 11. REQUIREMENTS ARRAY NORMALIZATION
// ============================================================

function getRequirementArray(value) {

  if (
    value === undefined ||
    value === null ||
    String(value).trim() === ""
  ) {
    return [];
  }


  if (Array.isArray(value)) {

    return value
      .map(x => normalize(x))
      .filter(
        x => x !== "unknown"
      );

  }


  return String(value)
    .split(";")
    .map(x => normalize(x))
    .filter(
      x => x !== "unknown"
    );

}


const expectedRequirements =
  getRequirementArray(
    expected.requirements
  );


const actualRequirements =
  getRequirementArray(
    actual.requirements
  );


// ============================================================
// 12. REQUIREMENT SEMANTIC ALIASES
// ============================================================

const requirementAliases = {

  pricing: [
    "pricing",
    "price",
    "prices",
    "cost",
    "costing",
    "quote",
    "quotation"
  ],

  availability: [
    "availability",
    "available",
    "in stock",
    "stock"
  ],

  options: [
    "options",
    "option",
    "choices",
    "choice",
    "alternatives",
    "alternative"
  ],

  delivery: [
    "delivery",
    "deliver",
    "delivered",
    "shipping",
    "shipment"
  ],

  quality: [
    "quality",
    "durable",
    "durability",
    "high quality"
  ],

  adjustable: [
    "adjustable",
    "adjustment",
    "adjustable height"
  ],

  color: [
    "color",
    "colour",
    "finish"
  ],

  material: [
    "material",
    "wood",
    "metal",
    "leather",
    "fabric"
  ]

};


// ============================================================
// 13. REQUIREMENT SEMANTIC MATCHING
// ============================================================

function requirementMatches(
  expectedReq,
  actualReq
) {

  // Direct phrase match
  if (
    actualReq.includes(expectedReq) ||
    expectedReq.includes(actualReq)
  ) {

    return true;

  }


  // Alias-based semantic match
  for (
    const [concept, aliases]
    of Object.entries(
      requirementAliases
    )
  ) {

    const expectedHasConcept =
      aliases.some(
        alias =>
          expectedReq.includes(alias)
      );


    const actualHasConcept =
      aliases.some(
        alias =>
          actualReq.includes(alias)
      );


    if (
      expectedHasConcept &&
      actualHasConcept
    ) {

      return true;

    }

  }


  return false;

}


// ============================================================
// 14. REQUIREMENTS QUALITY
// ============================================================

let requirementMatchesCount = 0;

const requirement_results = [];


for (
  const expectedReq
  of expectedRequirements
) {

  let matched = false;

  let matchedActual = null;


  for (
    const actualReq
    of actualRequirements
  ) {

    if (
      requirementMatches(
        expectedReq,
        actualReq
      )
    ) {

      matched = true;

      matchedActual =
        actualReq;

      break;

    }

  }


  if (matched) {
    requirementMatchesCount++;
  }


  requirement_results.push({

    expected:
      expectedReq,

    matched:
      matched,

    actual:
      matchedActual

  });

}


let requirements_quality_score = 1;


if (
  expectedRequirements.length > 0
) {

  requirements_quality_score =
    Number(
      (
        requirementMatchesCount /
        expectedRequirements.length
      ).toFixed(2)
    );

}


// ============================================================
// 15. NON-INVENTION / GROUNDING
// ============================================================

const inquiryEmailRaw =
  String(
    dataset.inquiry_email || ""
  ).toLowerCase();


const inventionFields = [
  "customer_name",
  "customer_email",
  "product_interest",
  "budget",
  "quantity",
  "urgency"
];


let nonInventionPass = true;

const non_invention_results = {};


// ============================================================
// 16. FIELD GROUNDING
// ============================================================

for (
  const field
  of inventionFields
) {

  const value =
    actual[field];


  const normalizedValue =
    normalize(value);


  // ----------------------------------------------------------
  // Unknown is valid and cannot be an invention
  // ----------------------------------------------------------

  if (
    normalizedValue === "unknown"
  ) {

    non_invention_results[field] = {

      value:
        "unknown",

      supported:
        true

    };

    continue;

  }


  let supported = false;


  // ----------------------------------------------------------
  // Customer name
  // ----------------------------------------------------------

  if (
    field === "customer_name"
  ) {

    supported =
      inquiryEmailRaw.includes(
        normalizedValue
      );

  }


  // ----------------------------------------------------------
  // Customer email
  // ----------------------------------------------------------

  else if (
    field === "customer_email"
  ) {

    supported =
      inquiryEmailRaw.includes(
        normalizedValue
      );

  }


  // ----------------------------------------------------------
  // Budget
  // ----------------------------------------------------------

  else if (
    field === "budget"
  ) {

    const actualMoney =
      normalizeMoney(value);


    const sourceMoneyValues =
      inquiryEmailRaw.match(
        /(?:\$|usd|inr|₹)?\s*\d[\d,]*(?:\.\d+)?/gi
      ) || [];


    supported =
      sourceMoneyValues.some(
        sourceValue =>
          normalizeMoney(
            sourceValue
          ) === actualMoney
      );


    // Also check "under $800", "up to $800", etc.
    if (!supported) {

      const sourceNormalized =
        inquiryEmailRaw
          .replace(/,/g, "")
          .replace(/\$/g, "");


      supported =
        sourceNormalized.includes(
          actualMoney
        );

    }

  }


  // ----------------------------------------------------------
  // Quantity
  // ----------------------------------------------------------

  else if (
    field === "quantity"
  ) {

    const actualQuantity =
      normalizeQuantity(value);


    const sourceQuantityValues =
      inquiryEmailRaw.match(
        /\b\d+(?:\.\d+)?\b/g
      ) || [];


    supported =
      sourceQuantityValues.some(
        sourceValue =>
          normalizeQuantity(
            sourceValue
          ) === actualQuantity
      );

  }


  // ----------------------------------------------------------
  // Product interest
  // ----------------------------------------------------------

  else if (
    field === "product_interest"
  ) {

    supported =
      inquiryEmailRaw.includes(
        normalizedValue
      );


    if (!supported) {

      const words =
        normalizedValue
          .split(/\s+/)
          .filter(
            word =>
              word.length > 2
          );


      const matchedWords =
        words.filter(
          word =>
            inquiryEmailRaw.includes(
              word
            )
        );


      supported =
        words.length > 0 &&
        (
          matchedWords.length /
          words.length
        ) >= 0.5;

    }

  }


  // ----------------------------------------------------------
  // Urgency
  // ----------------------------------------------------------

  else if (
    field === "urgency"
  ) {

    const urgency =
      normalizeUrgency(value);


    supported =
      inquiryEmailRaw.includes(
        urgency
      );


    if (!supported) {

      const words =
        urgency
          .split(/\s+/)
          .filter(
            word =>
              word.length > 2
          );


      const matchedWords =
        words.filter(
          word =>
            inquiryEmailRaw.includes(
              word
            )
        );


      supported =
        words.length > 0 &&
        (
          matchedWords.length /
          words.length
        ) >= 0.5;

    }

  }


  non_invention_results[field] = {

    value:
      normalizedValue,

    supported:
      supported

  };


  if (!supported) {

    nonInventionPass =
      false;

  }

}


// ============================================================
// 17. REQUIREMENT GROUNDING
// ============================================================
//
// Requirements can be paraphrased.
//
// Example:
//
// Email:
// "We need them delivered by end of this month."
//
// Extracted:
// "delivery by end of this month"
//
// This is considered grounded.
// ============================================================

const stopWords = new Set([
  "the",
  "a",
  "an",
  "and",
  "or",
  "with",
  "for",
  "to",
  "by",
  "of",
  "in",
  "on",
  "is",
  "are",
  "we",
  "us",
  "our",
  "please",
  "need",
  "want",
  "would",
  "like",
  "send",
  "me",
  "them"
]);


for (
  const requirement
  of actualRequirements
) {

  // Direct phrase match
  let supported =
    inquiryEmailRaw.includes(
      requirement
    );


  // Keyword coverage fallback
  if (!supported) {

    const requirementWords =
      requirement
        .replace(
          /[^a-z0-9\s]/g,
          " "
        )
        .split(/\s+/)
        .filter(
          word =>
            word.length > 2 &&
            !stopWords.has(word)
        );


    if (
      requirementWords.length > 0
    ) {

      const matchedWords =
        requirementWords.filter(
          word =>
            inquiryEmailRaw.includes(
              word
            )
        );


      supported =
        (
          matchedWords.length /
          requirementWords.length
        ) >= 0.5;

    }

  }


  non_invention_results[
    `requirement:${requirement}`
  ] = {

    value:
      requirement,

    supported:
      supported

  };


  if (!supported) {

    nonInventionPass =
      false;

  }

}


const non_invention_pass =
  nonInventionPass
    ? 1
    : 0;


// ============================================================
// 18. OVERALL SCORE
// ============================================================

const overall_score =
  Number(
    (
      (
        field_extraction_accuracy +
        completeness_score +
        format_compliance +
        requirements_quality_score +
        non_invention_pass
      ) / 5
    ).toFixed(2)
  );


// ============================================================
// 19. FINAL VERDICT
// ============================================================
//
// PASS when:
//
// Field extraction >= 80%
// Completeness = 100%
// Format = PASS
// Requirements quality >= 75%
// Non-invention = PASS
// ============================================================

const overall_verdict =
  (
    field_extraction_accuracy >= 0.80 &&
    completeness_score === 1 &&
    format_compliance === 1 &&
    requirements_quality_score >= 0.75 &&
    non_invention_pass === 1
  )
    ? "PASS"
    : "FAIL";


// ============================================================
// 20. EVALUATION NOTES
// ============================================================

const evaluation_notes =
  `Field extraction: ${correct}/${fields.length} correct. ` +
  `Completeness: ${presentFields}/${requiredFields.length} fields present. ` +
  `Format: ${format_compliance === 1 ? "PASS" : "FAIL"}. ` +
  `Requirements quality: ${requirementMatchesCount}/${expectedRequirements.length} matched. ` +
  `Non-invention: ${non_invention_pass === 1 ? "PASS" : "FAIL"}. ` +
  `Overall verdict: ${overall_verdict}.`;


// ============================================================
// 21. FINAL OUTPUT
// ============================================================

return {
  json: {

    test_id:
      dataset.test_id,

    field_extraction_accuracy:
      field_extraction_accuracy,

    completeness_score:
      completeness_score,

    format_compliance:
      format_compliance,

    non_invention_pass:
      non_invention_pass,

    requirements_quality_score:
      requirements_quality_score,

    overall_score:
      overall_score,

    overall_verdict:
      overall_verdict,

    field_results:
      field_results,

    completeness_results:
      completeness_results,

    requirement_results:
      requirement_results,

    non_invention_results:
      non_invention_results,

    evaluation_notes:
      evaluation_notes

  }
};

