{
  "type": "object",
  "properties": {
    "lead_tier": {
      "type": "string",
      "description": "Lead classification based on buying signals.",
      "enum": [
        "HOT",
        "WARM",
        "COLD",
        "NON_LEAD"
      ]
    },
    "is_sales_lead": {
      "type": "integer",
      "description": "1 if this is a genuine sales opportunity, 0 otherwise.",
      "enum": [
        0,
        1
      ]
    },
    "qualification_signals": {
      "type": "array",
      "description": "Key buying or non-sales signals supported by the structured input.",
      "items": {
        "type": "string"
      }
    },
    "confidence": {
      "type": "string",
      "description": "Confidence or uncertainty in the classification.",
      "enum": [
        "HIGH",
        "MEDIUM",
        "LOW"
      ]
    }
  },
  "required": [
    "lead_tier",
    "is_sales_lead",
    "qualification_signals",
    "confidence"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "recommendation_correctness": {
      "type": "string",
      "enum": ["PASS", "FAIL"],
      "description": "Whether the recommended products are relevant to the customer's primary product requirement."
    },
    "requirement_matching": {
      "type": "string",
      "enum": ["PASS", "FAIL"],
      "description": "Whether the recommended products satisfy the customer's explicit requirements based only on the provided catalog evidence."
    },
    "groundedness": {
      "type": "string",
      "enum": ["PASS", "FAIL"],
      "description": "Whether product-specific claims in the recommendation are supported by the provided product catalog or retrieved catalog evidence."
    },
    "status_correctness": {
      "type": "string",
      "enum": ["PASS", "FAIL"],
      "description": "Whether the actual recommendation status exactly matches the expected status."
    },
    "overall_result": {
      "type": "string",
      "enum": ["PASS", "FAIL"],
      "description": "PASS only when recommendation_correctness, requirement_matching, groundedness, and status_correctness are all PASS."
    },
    "reason": {
      "type": "string",
      "description": "A concise explanation of the most important reason for the evaluation result."
    }
  },
  "required": [
    "recommendation_correctness",
    "requirement_matching",
    "groundedness",
    "status_correctness",
    "overall_result",
    "reason"
  ],
  "additionalProperties": false
}

