// ==========================================
// SALES GENIE - FINAL WORKFLOW EVALUATION
// ==========================================

// ---------- EXPECTED VALUES ----------

const expected = $('When fetching a dataset row').first().json;

const test_id = expected.test_id || '';

const expectedLead =
  expected.expected_lead_classification || '';

const expectedProduct =
  expected.expected_product_id || '';

const expectedProductName =
  expected.expected_product_name || '';


// ==========================================
// ACTUAL LEAD QUALIFIER OUTPUT
// ==========================================

const leadRaw =
  $('Lead Qualifier Agent').first().json.output;

const leadOutput =
  typeof leadRaw === 'string'
    ? JSON.parse(leadRaw)
    : leadRaw;

const actualLead =
  leadOutput.lead_tier || '';


// ==========================================
// ACTUAL PRODUCT RECOMMENDER OUTPUT
// ==========================================

const productRaw =
  $('Product Recommender Agent').first().json.output;

const productOutput =
  typeof productRaw === 'string'
    ? JSON.parse(productRaw)
    : productRaw;

const recommendations =
  productOutput.recommendations || [];

const actualProduct =
  recommendations.length > 0
    ? recommendations[0].product_id || ''
    : '';


// ==========================================
// ACTUAL RESPONSE DRAFTER OUTPUT
// ==========================================

const drafterRaw =
  $('Response Drafter Agent').first().json.output;

const drafterOutput =
  typeof drafterRaw === 'string'
    ? JSON.parse(drafterRaw)
    : drafterRaw;

const responseBody =
  drafterOutput.body || '';


// ==========================================
// 1. LEAD ACCURACY
// ==========================================

const lead_accuracy =
  expectedLead.toString().trim().toUpperCase() ===
  actualLead.toString().trim().toUpperCase()
    ? 1
    : 0;


// ==========================================
// 2. SALES ACCURACY
// ==========================================

let sales_accuracy;

if (
  expectedProduct.toString().trim() === '' &&
  actualProduct.toString().trim() === ''
) {
  sales_accuracy = 1;
}
else {
  sales_accuracy =
    expectedProduct.toString().trim().toUpperCase() ===
    actualProduct.toString().trim().toUpperCase()
      ? 1
      : 0;
}


// ==========================================
// 3. RESPONSE ACCURACY
// ==========================================

let response_accuracy;

if (expectedProductName.toString().trim() === '') {

  response_accuracy =
    responseBody.toString().trim() !== ''
      ? 1
      : 0;

}
else {

  response_accuracy =
    responseBody
      .toString()
      .toLowerCase()
      .includes(
        expectedProductName.toString().toLowerCase()
      )
      ? 1
      : 0;
}


// ==========================================
// 4. OVERALL ACCURACY
// ==========================================

const overall_accuracy =
  (
    lead_accuracy +
    sales_accuracy +
    response_accuracy
  ) / 3;


// ==========================================
// 5. FINAL STATUS
// ==========================================

const status =
  overall_accuracy === 1
    ? 'PASS'
    : 'FAIL';


// ==========================================
// FINAL OUTPUT
// ==========================================

return [
  {
    json: {
      test_id,

      expected_lead: expectedLead,
      actual_lead: actualLead,

      expected_product: expectedProduct,
      actual_product: actualProduct,

      lead_accuracy,
      sales_accuracy,
      response_accuracy,

      overall_accuracy:
        Number(overall_accuracy.toFixed(2)),

      status
    }
  }
];

