// ==================================================
// SALES GENIE - CRM RULE ENFORCEMENT
// ==================================================

// --------------------------------------------------
// GET DATA FROM CURRENT CRM AGENT
// --------------------------------------------------

let crmData = $json.output ?? $json;

if (typeof crmData === "string") {
  try {
    crmData = JSON.parse(crmData);
  } catch (error) {
    throw new Error("CRM Agent output is not valid JSON");
  }
}


// --------------------------------------------------
// GET EMAIL INGESTION DATA
// --------------------------------------------------

const emailNode = $('Email Ingestion Agent').first().json;

let emailData = emailNode.output ?? emailNode;

if (typeof emailData === "string") {
  try {
    emailData = JSON.parse(emailData);
  } catch (error) {
    throw new Error("Email Ingestion Agent output is not valid JSON");
  }
}


// --------------------------------------------------
// GET LEAD QUALIFIER DATA
// --------------------------------------------------

const qualifierNode = $('Lead Qualifier Agent').first().json;

let qualifierData = qualifierNode.output ?? qualifierNode;

if (typeof qualifierData === "string") {
  try {
    qualifierData = JSON.parse(qualifierData);
  } catch (error) {
    throw new Error("Lead Qualifier Agent output is not valid JSON");
  }
}


// ==================================================
// AUTHORITATIVE VALUES
// ==================================================

// Customer information comes from Email Ingestion
const customerName =
  emailData.customer_name || "Anonymous";

const email =
  emailData.customer_email || "";

const productInterest =
  crmData.product_interest || emailData.product_interest || "Unknown";

const budget =
  emailData.budget ?? "Unknown";


// ==================================================
// URGENCY
// ==================================================
// IMPORTANT:
// NEVER calculate urgency from lead tier.
//
// CRM update agent is the source of truth.

const urgencyRaw = crmData.urgency;

const urgency =
  urgencyRaw &&
  ["low", "medium", "high", "urgent"].includes(
    String(urgencyRaw).trim().toLowerCase()
  )
    ? String(urgencyRaw).trim()
    : "Low";


// ==================================================
// LEAD TIER
// ==================================================

const rawTier =
  qualifierData.lead_tier || "";

const tier =
  String(rawTier).trim().toLowerCase();

let leadTier = "Unknown";

if (tier === "hot") {
  leadTier = "Hot";
}

else if (tier === "warm") {
  leadTier = "Warm";
}

else if (tier === "cold") {
  leadTier = "Cold";
}


// ==================================================
// LEAD ID
// ==================================================

const testId =
  crmData.test_id ||
  emailData.test_id ||
  "";

let leadId = crmData.lead_id || "";

if (!leadId && testId) {
  const match = String(testId)
    .trim()
    .match(/^E(\d+)$/i);

  if (match) {
    leadId = "L" + match[1].padStart(3, "0");
  }
}


// ==================================================
// STATUS
// ==================================================

let status = "Open";


// Cold
if (tier === "cold") {
  status = "Needs Info";
}

// Unknown / non-sales
else if (
  tier === "unknown" ||
  tier === "spam" ||
  tier === "invalid" ||
  tier === "non_sales" ||
  tier === "support"
) {
  status = "Needs Info";
}

// Warm
else if (tier === "warm") {
  status = "Open";
}

// Hot
else if (tier === "hot") {

  // IMPORTANT:
  // For now preserve the CRM Agent's validated status.
  // Do not infer Quoted from lead tier alone.

  const crmStatus =
    String(crmData.status || "")
      .trim()
      .toLowerCase();

  if (crmStatus === "quoted") {
    status = "Quoted";
  }

  else if (crmStatus === "in progress") {
    status = "In Progress";
  }

  else {
    status = "Open";
  }
}


// ==================================================
// ASSIGNED TO
// ==================================================

const product =
  String(productInterest)
    .trim()
    .toLowerCase();

let assignedTo = "Unassigned";

if (
  tier !== "cold" &&
  tier !== "unknown" &&
  tier !== "spam" &&
  tier !== "invalid" &&
  tier !== "non_sales" &&
  tier !== "support"
) {

  if (product.includes("desk")) {
    assignedTo = "Rep A";
  }

  else if (product.includes("chair")) {
    assignedTo = "Rep B";
  }

  else if (product.includes("table")) {
    assignedTo = "Rep C";
  }

  else if (product.includes("office furniture")) {
    assignedTo = "Rep C";
  }

  else if (product.includes("office package")) {
    assignedTo = "Rep C";
  }
}


// ==================================================
// CREATED AT
// ==================================================

const createdAt =
  new Date().toISOString().split("T")[0];


// ==================================================
// FINAL CRM RECORD
// ==================================================

return {
  json: {

    lead_id: leadId,

    created_at: createdAt,

    customer_name: customerName,

    email: email,

    lead_tier: leadTier,

    product_interest: productInterest,

    budget: budget,

    // IMPORTANT:
    // This comes directly from Email Ingestion.
    urgency: urgency,

    source: "Email",

    status: status,

    assigned_to: assignedTo,

    notes: crmData.notes || ""
  }
};

// ============================================================
// SALES GENIE - CRM OUTPUT EVALUATION
// ============================================================
// Golden Dataset = single source of truth
// Current node input = final CRM Rule Enforcement output
// ============================================================


// ------------------------------------------------------------
// 1. GET GOLDEN DATASET ROW
// ------------------------------------------------------------
const dataset = $("When fetching a dataset row").item.json;


// ------------------------------------------------------------
// 2. GET ACTUAL CRM OUTPUT
// Current node receives output from CRM Rule Enforcement
// ------------------------------------------------------------
let actual = $input.first().json;


// ------------------------------------------------------------
// 3. HANDLE output WRAPPER IF PRESENT
// ------------------------------------------------------------
if (actual.output !== undefined) {

  let parsed = actual.output;

  if (typeof parsed === "string") {
    try {
      parsed = JSON.parse(parsed);
    } catch (e) {
      return {
        json: {
          crm_field_accuracy: 0,
          crm_record_completeness: 0,
          data_preservation_non_invention: 0,
          crm_schema_compliance: 0,
          rule_enforcement_accuracy: 0,
          error: "Invalid JSON in CRM output",
          raw_output: actual.output
        }
      };
    }
  }

  actual = parsed;
}


// ------------------------------------------------------------
// 4. NORMALIZATION
// ------------------------------------------------------------
function normalize(value) {

  if (
    value === undefined ||
    value === null ||
    String(value).trim() === ""
  ) {
    return "unknown";
  }

  return String(value)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}


// ------------------------------------------------------------
// 5. EXPECTED CRM VALUES FROM GOLDEN DATASET
// ------------------------------------------------------------
const expected = {

 // lead_id:
   // dataset.expected_crm_lead_id,

  customer_name:
    dataset.expected_customer_name,

  email:
    dataset.expected_email,

  lead_tier:
    dataset.expected_lead_classification,

  product_interest:
    dataset.expected_product_interest,

  budget:
    dataset.expected_budget,

  source:
    dataset.expected_crm_source,

  notes:
    dataset.expected_crm_notes,

  action:
    dataset.expected_crm_action
};


// ------------------------------------------------------------
// 6. CRM FIELD ACCURACY
//
// These fields should be preserved/mapped into CRM.
// Do NOT include urgency/status/assigned_to here because
// those are generated by CRM Rule Enforcement.
// ------------------------------------------------------------
const accuracyFields = [
 // "lead_id",
  "customer_name",
  "email",
  "lead_tier",
  "product_interest",
  "budget",
  "source"
];

let correctFields = 0;

const fieldResults = {};

for (const field of accuracyFields) {

  const expectedValue =
    normalize(expected[field]);

  const actualValue =
    normalize(actual[field]);

  const correct =
    expectedValue === actualValue;

  fieldResults[field] = {
    expected: expectedValue,
    actual: actualValue,
    correct
  };

  if (correct) {
    correctFields++;
  }
}

const crmFieldAccuracy =
  (correctFields / accuracyFields.length) * 100;


// ------------------------------------------------------------
// 7. CRM RECORD COMPLETENESS
//
// Final CRM schema = 11 fields.
// ------------------------------------------------------------
const requiredFields = [
  "lead_id",
  "customer_name",
  "email",
  "lead_tier",
  "product_interest",
  "budget",
  "urgency",
  "source",
  "status",
  "assigned_to",
  "notes"
];

let populatedFields = 0;

for (const field of requiredFields) {

  const value = actual[field];

  if (
    value !== undefined &&
    value !== null &&
    String(value).trim() !== ""
  ) {
    populatedFields++;
  }
}

const crmRecordCompleteness =
  (populatedFields / requiredFields.length) * 100;


// ------------------------------------------------------------
// 8. DATA PRESERVATION / NON-INVENTION
//
// Compare source input against CRM output.
// ------------------------------------------------------------
const preservationFields = [
  "customer_name",
  "email",
  "product_interest",
  "lead_tier"
];

let preservationChecked = 0;
let preservationPassed = 0;

const preservationResults = {};

for (const field of preservationFields) {

  const inputValue =
    normalize(dataset[`input_${field}`]);

  const outputValue =
    normalize(actual[field]);

  // No source value = nothing to validate
  if (inputValue === "unknown") {

   const preserved = outputValue === "unknown";

  preservationResults[field] = {
    checked: true,
    input: "unknown",
    output: outputValue,
    preserved
  };

  preservationChecked++;

  if (preserved) {
    preservationPassed++;
  }

  continue;
}

  preservationChecked++;

  const preserved =
    inputValue === outputValue;

  preservationResults[field] = {

    checked: true,

    input:
      inputValue,

    output:
      outputValue,

    preserved
  };

  if (preserved) {
    preservationPassed++;
  }
}

const preservationScore =
  preservationChecked === 0
    ? 100
    : (preservationPassed / preservationChecked) * 100;


// ------------------------------------------------------------
// 9. CRM SCHEMA COMPLIANCE
// ------------------------------------------------------------
const expectedSchema = [
  "lead_id",
  "customer_name",
  "email",
  "lead_tier",
  "product_interest",
  "budget",
  "urgency",
  "source",
  "status",
  "assigned_to",
  "notes"
];

const actualSchema =
  Object.keys(actual);

const missingFields =
  expectedSchema.filter(
    field => !actualSchema.includes(field)
  );

const extraFields =
  actualSchema.filter(
    field => !expectedSchema.includes(field)
  );

const schemaCompliant =
  missingFields.length === 0 &&
  extraFields.length === 0;


// ------------------------------------------------------------
// 10. CRM RULE ENFORCEMENT EVALUATION
//
// These values are NOT expected from the AI agent.
// They are generated deterministically by Rule Enforcement.
// ------------------------------------------------------------
const tier =
  normalize(expected.lead_tier);

const product =
  normalize(expected.product_interest);


// ------------------------------------------------------------
// EXPECTED URGENCY
// ------------------------------------------------------------
let expectedUrgency = "Low";

if (tier === "hot") {
  expectedUrgency = "High";
}

if (tier === "warm") {
  expectedUrgency = "Medium";
}


// ------------------------------------------------------------
// EXPECTED STATUS
// ------------------------------------------------------------
let expectedStatus = "Needs Info";

if (tier === "hot") {
  expectedStatus = "Quoted";
}

if (tier === "warm") {
  expectedStatus = "Open";
}

if (tier === "cold") {
  expectedStatus = "Needs Info";
}

if (
  tier === "non_lead" ||
  tier === "non_sales/support"
) {
  expectedStatus = "Needs Info";
}


// ------------------------------------------------------------
// EXPECTED ASSIGNMENT
// ------------------------------------------------------------
let expectedAssignedTo = "Unassigned";

if (product.includes("desk")) {
  expectedAssignedTo = "Rep A";
}

if (product.includes("chair")) {
  expectedAssignedTo = "Rep B";
}

if (product.includes("table")) {
  expectedAssignedTo = "Rep C";
}

if (product.includes("office furniture")) {
  expectedAssignedTo = "Rep C";
}

if (product.includes("office package")) {
  expectedAssignedTo = "Rep C";
}

if (product.includes("enterprise")) {
  expectedAssignedTo = "Rep C";
}


// Cold / non-lead should remain unassigned
if (
  tier === "cold" ||
  tier === "non_lead" ||
  tier === "non_sales/support"
) {
  expectedAssignedTo = "Unassigned";
}


// ------------------------------------------------------------
// 11. RULE RESULTS
// ------------------------------------------------------------
const ruleResults = {

  urgency: {

    expected:
      expectedUrgency,

    actual:
      actual.urgency,

    correct:
      normalize(actual.urgency) ===
      normalize(expectedUrgency)
  },

  status: {

    expected:
      expectedStatus,

    actual:
      actual.status,

    correct:
      normalize(actual.status) ===
      normalize(expectedStatus)
  },

  assigned_to: {

    expected:
      expectedAssignedTo,

    actual:
      actual.assigned_to,

    correct:
      normalize(actual.assigned_to) ===
      normalize(expectedAssignedTo)
  }
};


const ruleChecks = [
  ruleResults.urgency.correct,
  ruleResults.status.correct,
  ruleResults.assigned_to.correct
];

const ruleEnforcementAccuracy =
  (
    ruleChecks.filter(Boolean).length /
    ruleChecks.length
  ) * 100;


// ------------------------------------------------------------
// 12. NOTES COMPLETENESS
//
// We don't require exact notes text because the agent can
// legitimately phrase the same information differently.
// ------------------------------------------------------------
const notesPresent =
  actual.notes !== undefined &&
  actual.notes !== null &&
  String(actual.notes).trim() !== "";


// ------------------------------------------------------------
// 13. CRM ACTION
//
// Golden dataset says CREATE or NO_CRM.
// If this evaluator receives a CRM record, it means CREATE.
// ------------------------------------------------------------
const actualCrmAction =
  Object.keys(actual).length > 0 &&
  (
    actual.lead_id !== undefined ||
    actual.customer_name !== undefined ||
    actual.product_interest !== undefined
  )
    ? "CREATE"
    : "NO_CRM";

const crmActionCorrect =
  normalize(expected.action) ===
  normalize(actualCrmAction);


// ------------------------------------------------------------
// 14. FINAL EVALUATION OUTPUT
// ------------------------------------------------------------
return {
  json: {

    test_id:
      dataset.test_id,

    // -----------------------------
    // CRM AGENT METRICS
    // -----------------------------

    crm_field_accuracy:
      Number(
        crmFieldAccuracy.toFixed(2)
      ),

    crm_record_completeness:
      Number(
        crmRecordCompleteness.toFixed(2)
      ),

    data_preservation_non_invention:
      Number(
        preservationScore.toFixed(2)
      ),

    crm_schema_compliance:
      schemaCompliant
        ? 100
        : 0,

    // -----------------------------
    // CRM RULE METRIC
    // -----------------------------

    rule_enforcement_accuracy:
      Number(
        ruleEnforcementAccuracy.toFixed(2)
      ),

    // -----------------------------
    // CRM ACTION
    // -----------------------------

    crm_action_accuracy:
      crmActionCorrect
        ? 100
        : 0,

    // -----------------------------
    // SUPPORTING DIAGNOSTICS
    // -----------------------------

    field_results:
      fieldResults,

    preservation_results:
      preservationResults,

    rule_results:
      ruleResults,

    schema_missing_fields:
      missingFields,

    schema_extra_fields:
      extraFields,

    schema_compliant:
      schemaCompliant,

    notes_present:
      notesPresent,

    expected_crm_action:
      expected.action,

    actual_crm_action:
      actualCrmAction
  }
};

