// ==========================================
// LEAD QUALIFIER EVALUATION
// ==========================================

// Expected values from Golden Dataset
const expected = $('When fetching a dataset row').first().json;

const expectedLeadTier =
  (expected.expected_lead_classification || '').toString().trim().toUpperCase();

const expectedNonLead =
  expected.expected_non_lead;


// Convert expected_non_lead into expected is_sales_lead
// non_lead = 0  → sales lead = 1
// non_lead = 1  → sales lead = 0

const expectedIsSalesLead =
  Number(expectedNonLead) === 1 ? 0 : 1;


// ==========================================
// Actual Lead Qualifier output
// ==========================================

const rawOutput =
  $('Lead Qualifier Agent').first().json.output;

const actual =
  typeof rawOutput === 'string'
    ? JSON.parse(rawOutput)
    : rawOutput;

const actualLeadTier =
  (actual.lead_tier || '').toString().trim().toUpperCase();

const actualIsSalesLead =
  Number(actual.is_sales_lead);


// ==========================================
// 1. LEAD TIER ACCURACY
// ==========================================

const lead_tier_accuracy =
  expectedLeadTier === actualLeadTier
    ? 1
    : 0;


// ==========================================
// 2. SALES LEAD ACCURACY
// ==========================================

const sales_lead_accuracy =
  expectedIsSalesLead === actualIsSalesLead
    ? 1
    : 0;


// ==========================================
// 3. QUALIFICATION SIGNAL SCORE
// ==========================================

// For now, don't penalize the agent because your
// Golden Dataset does not contain expected signals.

const qualification_signal_score = 1;


// ==========================================
// 4. CONFIDENCE VALIDITY
// ==========================================

const confidence =
  (actual.confidence || '').toString().trim().toUpperCase();

const confidence_validity =
  ['HIGH', 'MEDIUM', 'LOW'].includes(confidence)
    ? 1
    : 0;


// ==========================================
// 5. OVERALL SCORE
// ==========================================

const overall_score =
  (
    lead_tier_accuracy +
    sales_lead_accuracy +
    qualification_signal_score +
    confidence_validity
  ) / 4;


// ==========================================
// 6. VERDICT
// ==========================================

const overall_verdict =
  overall_score === 1
    ? 'PASS'
    : 'FAIL';


// ==========================================
// FINAL OUTPUT
// ==========================================

return [
  {
    json: {
      test_id: expected.test_id,

      expected_lead_tier: expectedLeadTier,
      actual_lead_tier: actualLeadTier,

      expected_is_sales_lead: expectedIsSalesLead,
      actual_is_sales_lead: actualIsSalesLead,

      lead_tier_accuracy,
      sales_lead_accuracy,
      qualification_signal_score,
      confidence_validity,

      overall_score: Number(overall_score.toFixed(2)),

      overall_verdict
    }
  }
];

